import { chromium } from '@playwright/test';
async function run(viewport){
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport });
  page.on('console', msg => console.log('console', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('pageerror', err.message));
  await page.goto('http://127.0.0.1:3012/', { waitUntil: 'networkidle' });
  console.log('viewport', viewport.width, 'brand', await page.locator(viewport.width < 960 ? '.mtop' : '.app-shell > .sidebar').getByText('POWERPROMPT').isVisible());
  console.log('searchbar initial open', await page.locator('.searchbar.open').count());
  await page.getByRole('button', { name: /Reveal search/ }).click();
  console.log('searchbar after click', await page.locator('.searchbar.open').count());
  await page.getByPlaceholder(/Search prompts/).fill('cold email');
  console.log('article count', await page.getByRole('button', { name: 'Open The Cold-Email Closer' }).count());
  await page.getByRole('button', { name: 'Open The Cold-Email Closer' }).click({ force: true });
  await page.waitForTimeout(300);
  console.log('dialog', await page.getByRole('dialog').count(), 'lb', await page.locator('.lb.open').count());
  if(viewport.width < 960){
    await page.getByRole('button', { name: 'Menu' }).click({ force: true });
    await page.waitForTimeout(300);
    console.log('drawer after click', await page.locator('.mobile-drawer.open').count(), await page.locator('.mobile-drawer').evaluateAll(els => els.map(e => e.className)));
  }
  await browser.close();
}
await run({width:1280,height:900});
await run({width:390,height:844});
